import json,pathlib,time,sys
import numpy as np
ROOT=pathlib.Path('/app/output')
def latest():
 p=pathlib.Path((ROOT/'latest.txt').read_text());return p,json.loads((p/'meta.json').read_text())
def point(cam,u,v):
 p,m=latest();cam='robot0_'+cam
 d=np.load(p/f'depth_{cam}.npy').squeeze();c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);z=float(d[v,u]);q=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);return (T@q)[:3]
def state():
 p,m=latest();s=dict(zip(m['proprio']['layout'],m['proprio']['now'])); print(p,'remaining',m['time_left_s']);print({k:round(v,5) for k,v in s.items() if k.endswith('_pos') or k.startswith('eef')})
def send(c):
 old=(ROOT/'latest.txt').read_text();(ROOT/'command.json').write_text(json.dumps(c))
 for i in range(1200):
  time.sleep(.1)
  if (ROOT/'latest.txt').read_text()!=old:break
 else:raise RuntimeError('timeout')
 state()
if __name__=='__main__':
 if sys.argv[1]=='state':state()
 elif sys.argv[1]=='point':
  cam=sys.argv[2]
  for i in range(3,len(sys.argv),2):print(sys.argv[i:i+2],point(cam,int(sys.argv[i]),int(sys.argv[i+1])))
 elif sys.argv[1]=='act':send({'op':'act','a':list(map(float,sys.argv[3:])), 'n':int(sys.argv[2])})
 elif sys.argv[1]=='obs':send({'op':'obs','seconds':float(sys.argv[2]) if len(sys.argv)>2 else 0})
